def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split off pre-release (everything after '-')
        if '-' in v_no_build:
            parts = v_no_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(int(x) for x in version_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part is not None:
            prerelease_ids = prerelease_part.split('.')
            prerelease_tuple = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    prerelease_tuple.append((0, int(identifier)))
                else:
                    prerelease_tuple.append((1, identifier))
            prerelease_tuple = tuple(prerelease_tuple)
        else:
            prerelease_tuple = None

        return version_nums, prerelease_tuple

    def sort_key(v):
        version_nums, prerelease_tuple = parse_version(v)

        # For sorting:
        # - Compare version numbers first
        # - If prerelease_tuple is None, it sorts after any prerelease (use a tuple that sorts after)
        # - If prerelease_tuple is not None, use it for comparison

        if prerelease_tuple is None:
            # No pre-release: sorts after pre-release versions
            return (version_nums, (1,))
        else:
            # Has pre-release: sorts before versions without pre-release
            return (version_nums, (0, prerelease_tuple))

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

